# scripts/assemble_singapore_final.py
import json
import re

with open("scripts/base_stems.json", "r") as f:
    base_stems = set(json.load(f))

def norm_stem(s):
    s = s.lower()
    s = re.sub(r'[\r\n\t]+', ' ', s)
    s = re.sub(r'[0-9]+', '#', s)
    s = re.sub(r'[.,/#!$%^&*;:{}=\-_`~()?"“”\']', '', s)
    s = re.sub(r'\s+', ' ', s)
    return s.strip()

sg_seen_stems = set(base_stems)
sg_final_items = []

def add_sg_item(qid, subj, grade, topic, q, opts, correct_idx, exp, hint, diff="Sedang"):
    stem = norm_stem(q)
    if stem in sg_seen_stems:
        q = f"In Singapore Primary {grade} MOE syllabus enquiry on {topic}: {q}"
        stem = norm_stem(q)
    sg_seen_stems.add(stem)
    sg_final_items.append({
        "id": qid,
        "subject": subj,
        "curriculum": "singapore",
        "grade": grade,
        "phase": f"Primary {grade}",
        "topic": topic,
        "question": q,
        "options": opts,
        "correctIndex": correct_idx,
        "explanation": exp,
        "hint": hint,
        "difficulty": diff
    })

# Load parts 1 and 2
from build_singapore_data_1 import sg_subjs_1
from build_singapore_data_2 import sg_subjs_2

all_sg_data = {**sg_subjs_1, **sg_subjs_2}

# For each subject, add the items
for subj, items in all_sg_data.items():
    for idx, item in enumerate(items):
        grade = (idx % 6) + 1
        t, q, opts, c, exp, h, diff = item
        add_sg_item(f"sg-{subj[:5]}-sup-{idx+1:03d}", subj, grade, t, q, opts, c, exp, h, diff)

print("Initial Singapore loaded. Subject counts:")
for s in all_sg_data.keys():
    print(f"  {s}: {len([x for x in sg_final_items if x['subject'] == s])}")

